var HSBC_Aggregated_email = Class.create();
HSBC_Aggregated_email.prototype = {
    initialize: function() {},
    //MSSRBXCE-888 Updating the System Property
    updateSystemProperty: function(property_sys_id, property_value) {
        var sysProperties = new GlideRecord('sys_properties');
        if (sysProperties.get(property_sys_id)) {
            sysProperties.value = property_value;
            var updateId = sysProperties.update();

            if (updateId) {
                gs.info('MSSRBXCE-888 - Updated XXXX');
            } else {
                gs.info('MSSRBXCE-888 - Not Updated XXXX');
            }

        }


        /*
        sysProperties = new GlideRecord('sys_properties');
        sysProperties.addQuery('sys_id', property_sys_id);
        sysProperties.query();
        if (sysProperties.next()) {
            gs.info('MSSRBXCE-888 sys_proprties value after action completed - ' + sysProperties.value);
		}	*/
    },
    //Below code is the custom sorting logic created for story MSSRBXCE-165
    scenario21: function(parent_number) {

        var childAggArrOfObj21 = [];
        try {
            var tradeId, tradeDate, valueDate, insID, quant, direction, currency, grossPrice;
            var childAggregatedRecords21 = new GlideRecord('x_hsb11_hsbcmss_eh_aggregated_trade_email_queue');
            childAggregatedRecords21.addQuery('parent.number', parent_number);
            // MSSRBXCE-443 excluding the records which is  actioned by Client and trade case status is cancelled.
            childAggregatedRecords21.addQuery('actioned=false^trade_case.state!=7');
            childAggregatedRecords21.query();

            while (childAggregatedRecords21.next()) {
                //Object to store values of fields of child table
                var recordValueObj = {
                    'tradeId': childAggregatedRecords21.getValue('block_trade_id'),
                    'tradeDate': childAggregatedRecords21.getValue('trade_date'),
                    'valueDate': childAggregatedRecords21.getValue('value_date'),
                    'insID': childAggregatedRecords21.getValue('instrument_id'),
					'ISIN': '' + childAggregatedQueue21.trade_case.financial_object.u_ctac_trade_audit_0_instrument_isin_s,
                    'quant': childAggregatedRecords21.getValue('quantity'),
                    'direction': childAggregatedRecords21.getValue('direction'),
                    'currency': childAggregatedRecords21.getValue('currency'),
                    'grossPrice': childAggregatedRecords21.getValue('gross_price')
                };

                childAggArrOfObj21.push(recordValueObj);
            }
            childAggArrOfObj21 = this.sortColumn(childAggArrOfObj21);
            //For loop to print the values in an email template
            for (var i = 0; i < childAggArrOfObj21.length; i++) {
                var item = childAggArrOfObj21[i];

                template.print('<tr style="border: 1px solid black;text-align:left;"><td style="border: 1px solid black;">' + item.tradeId + '</td><td style="border: 1px solid black;white-space:nowrap;">' + item.tradeDate + ' </td><td style="border: 1px solid black;white-space:nowrap;">' + item.valueDate + '</td><td style="border: 1px solid black;">' + item.insID + '</td><td style="border: 1px solid black;">' + item.ISIN + '</td><td style="border: 1px solid black;">' + item.quant + '</td><td style="border: 1px solid black;">' + item.direction + '</td><td style="border: 1px solid black;">' + item.currency + '</td><td style="border: 1px solid black;">' + item.grossPrice + '</td></tr>');

            }
        } catch (error) {
            gs.error(error);
        }
    },

    // Scenario13 sort Data function start
    ////Below code is the custom sorting logic created for story MSSRBXCE-189
    sortDataScenario13: function(parentNumber) {
        var childAggArrOfObj13 = [];

        try {
            var childAggregatedQueue13 = new GlideRecord('x_hsb11_hsbcmss_eh_aggregated_trade_email_queue');
            childAggregatedQueue13.addQuery('parent.number', parentNumber);
            // MSSRBXCE-443 excluding the records which is  actioned by Client and trade case status is cancelled.
            childAggregatedQueue13.addQuery('actioned=false^trade_case.state!=7');
            childAggregatedQueue13.query();
            while (childAggregatedQueue13.next()) {

                //Object to store values of fields of child table
                var recordValueObj13 = {
                    'tradeId': '' + childAggregatedQueue13.getValue('block_trade_id'),
                    'tradeDate': '' + childAggregatedQueue13.getValue('trade_date'),
                    'valueDate': '' + childAggregatedQueue13.getValue('value_date'),
                    'insID': '' + childAggregatedQueue13.getValue('instrument_id'),
                    'direction': '' + childAggregatedQueue13.getValue('direction'),
                    'grossPrice': '' + childAggregatedQueue13.getValue('gross_price'),
                    'currency': '' + childAggregatedQueue13.getValue('currency'),
                    'agent': '' + childAggregatedQueue13.getValue('fo_trader_name'),
                    'ISIN': '' + childAggregatedQueue13.trade_case.financial_object.u_ctac_trade_audit_0_instrument_isin_s,
                    'quantity': '' + childAggregatedQueue13.getValue('quantity'),
                    'mismatch': '' + childAggregatedQueue13.getValue('mismatched_fields'),
                    'allocationId': '' + childAggregatedQueue13.getValue('allocation_id'),
                    'fundId': '' + childAggregatedQueue13.getValue('fund_id_alert_code'),
                    'hsbc': '' + childAggregatedQueue13.getValue('hsbc_value'),
                    'cpty': '' + childAggregatedQueue13.getValue('cpty_value'),
                    'basketID': '' + childAggregatedQueue13.getValue('is_the_trade_linked_to_a_basket_id')
                };

                childAggArrOfObj13.push(recordValueObj13);
            }

            //Sorting all the records : Currency, Value Date, Direction, Instrument Identifier

            childAggArrOfObj13 = this.sortColumn(childAggArrOfObj13);

            for (var i = 0; i < childAggArrOfObj13.length; i++) {
                var item = childAggArrOfObj13[i];
                var mismatchArray = [];
                var cptyValueArray = [];
                var hsbcVaueArray = [];
                mismatchArray = item.mismatch.split(";");
                cptyValueArray = item.cpty.split(";");
                hsbcVaueArray = item.hsbc.split(";");

                for (var j = 0; j < mismatchArray.length; j++) {
                    // DealPrice fix
                    if (mismatchArray[j] == "DealPrice") mismatchArray[j] = "Deal Price";

                    template.print('<tr><td style="border: 1px solid black;">' + item.tradeId + '</td><td style="border: 1px solid black;white-space:nowrap;">' + item.tradeDate + '</td><td style="border: 1px solid black;white-space:nowrap;">' + item.valueDate + '</td><td style="border: 1px solid black;">' + item.insID + '</td><td style="border: 1px solid black;">' + item.ISIN + '</td><td style="border: 1px solid black;">' + item.quantity + '</td><td style="border: 1px solid black;">' + item.direction + '</td><td style="border: 1px solid black;">' + item.currency + '</td><td style="border: 1px solid black;">' + item.grossPrice + '</td><td style="border: 1px solid black;background-color: #ffff31;">' + mismatchArray[j] + '</td><td style="border: 1px solid black;background-color: #ffff31;">' + hsbcVaueArray[j] + '</td><td style="border: 1px solid black;background-color: #ffff31;">' + cptyValueArray[j] + '</td><td style="border: 1px solid black;">' + item.agent + '</td><td style="border: 1px solid black;"></td></tr>');
                }

            }
        } catch (error) {
            gs.error(error);
        }
    },

