    sortColumn: function(jsonObjArr) {

        function customSort(column1, column2) {

            var currencyComparison = column1.currency.localeCompare(column2.currency);

            if (currencyComparison === 0) {
                var dateA = new GlideDate();
                dateA.setDisplayValue(column1.valueDate, "dd MMM yyyy");

                var dateB = new GlideDate();
                dateB.setDisplayValue(column2.valueDate, "dd MMM yyyy");
                var dateComparison = dateA.compareTo(dateB);

                if (dateComparison === 0) {

                    var direct = column1.direction.localeCompare(column2.direction);

                    if (direct === 0)
                        return column1.insID.localeCompare(column2.insID);

                    return direct;
                }
                return dateComparison;
            }
            return currencyComparison;
        }
        jsonObjArr.sort(customSort);

        return jsonObjArr;
    },
